      LEFT JOIN replacement_candidates_by_ct_20260324 rc ON ct.ct_dguid = rc.ct_dguid;;
 CREATE MATERIALIZED VIEW regina.ct_direct_priority_ranking_20260324 AS  WITH base AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
