             ct_direct_lead_synthesis_20260324.lim_at_prevalence_pct,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
             ct_direct_lead_synthesis_20260324.unemployment_rate_pct,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
